def run_agent(question, model, tools, max_steps=6):
    seen, trace = set(), []
    state = {'question': question}
    for step in range(max_steps):
        call = model.decide(state, tools)          # {'tool': name, 'args': {...}} or {'answer': str}
        if 'answer' in call:
            return call['answer'], trace
        key = (call['tool'], tuple(sorted(call['args'].items())))
        if key in seen:
            return 'repeat detected, stopping', trace
        seen.add(key)
        out = tools[call['tool']](**call['args'])
        trace.append({'step': step, 'tool': call['tool'], 'args': call['args'], 'out': str(out)[:200]})
        state['last'] = out
    return 'step limit reached', trace

TOOLS = {}

def tool(name, description, schema):
    def deco(fn):
        TOOLS[name] = {'description': description, 'schema': schema, 'fn': fn}
        return fn
    return deco

def call(name, args):
    spec = TOOLS.get(name)
    if not spec:
        raise ValueError(f'unknown tool: {name}')
    missing = [k for k in spec['schema'].get('required', []) if k not in args]
    if missing:
        raise ValueError(f'missing args: {missing}')
    return spec['fn'](**args)

def with_idempotency(store, make_key):
    def wrap(fn):
        def inner(**args):
            key = make_key(**args)
            if key in store:
                return store[key]
            result = fn(**args)
            store[key] = result
            return result
        return inner
    return wrap

class Budget:
    def __init__(self, max_steps=6, max_tokens=20000):
        self.steps, self.tokens = 0, 0
        self.max_steps, self.max_tokens = max_steps, max_tokens
    def spend(self, tokens=0):
        self.steps += 1
        self.tokens += tokens
        if self.steps > self.max_steps:
            raise RuntimeError('step budget exceeded')
        if self.tokens > self.max_tokens:
            raise RuntimeError('token budget exceeded')

