ALLOWED = {'lookup', 'calculate', 'draft', 'confirm'}

def validate_plan(plan):
    problems = []
    if not isinstance(plan, list) or not plan:
        return ['plan must be a non-empty list']
    for i, step in enumerate(plan):
        if step.get('action') not in ALLOWED:
            problems.append(f'step {i}: action {step.get("action")} not allowed')
        if not str(step.get('why', '')).strip():
            problems.append(f'step {i}: missing rationale')
    return problems

import json, time

def audit_logger(path):
    def log(step, tool, args, result, tokens=0):
        with open(path, 'a', encoding='utf-8') as f:
            f.write(json.dumps({
                'ts': time.time(), 'step': step, 'tool': tool,
                'args': args, 'result': str(result)[:200], 'tokens': tokens,
            }) + '\n')
    return log

class Memory:
    def __init__(self, max_turns=6):
        self.summary = ''
        self.turns = []
        self.max_turns = max_turns
    def add(self, role, content):
        self.turns.append({'role': role, 'content': content})
        if len(self.turns) > self.max_turns:
            old = self.turns.pop(0)
            self.summary = (self.summary + ' ' + old['content'])[:1000]
    def context(self):
        return {'summary': self.summary, 'turns': self.turns[-self.max_turns:]}

def require_approval(action, amount, limit=1000, approve_fn=None):
    if amount <= limit:
        return True
    if approve_fn is None:
        raise PermissionError(f'{action} of {amount} needs approval')
    return bool(approve_fn(action, amount))

class ScriptedLLM:
    def __init__(self, script):
        self.script = list(script)
        self.seen = []
    def decide(self, state, tools):
        self.seen.append(state.get('question'))
        return self.script.pop(0) if self.script else {'answer': 'done'}

def with_fallback(primary, fallback, *args, **kwargs):
    try:
        return primary(*args, **kwargs), 'primary'
    except Exception as e:
        result = fallback(*args, **kwargs)
        return result, f'fallback ({type(e).__name__})'

