def validate_output(obj, schema):
    problems = []
    for field, typ in schema.items():
        if field not in obj:
            problems.append(f'missing {field}')
        elif not isinstance(obj[field], typ):
            problems.append(f'{field} must be {typ.__name__}')
    return problems

