from concurrent.futures import ThreadPoolExecutor, as_completed

def run_parallel(calls):
    results, errors = {}, {}
    with ThreadPoolExecutor(max_workers=4) as ex:
        futures = {ex.submit(fn, **args): name for name, (fn, args) in calls.items()}
        for fut in as_completed(futures):
            name = futures[fut]
            try:
                results[name] = fut.result()
            except Exception as e:
                errors[name] = f'{type(e).__name__}: {e}'
    return results, errors

import json

def parse_tool_json(text, repair=None):
    cleaned = text.strip()
    if cleaned.startswith('```'):
        cleaned = cleaned.split('```')[1]
        cleaned = cleaned[4:] if cleaned.lower().startswith('json') else cleaned
    start, end = cleaned.find('{'), cleaned.rfind('}')
    if start != -1 and end > start:
        try:
            return json.loads(cleaned[start:end + 1])
        except json.JSONDecodeError:
            pass
    if repair is not None:          # one bounded repair attempt, never a loop
        return json.loads(repair(text))
    raise ValueError('unparseable tool output')

def print_trace(trace):
